// 9.2.1. Identification.
//
// Defines the identity management model: how identities are created,
// sourced, verified, federated, and mapped. Covers identity sources,
// identity providers, verification/proofing, SSO, self-registration,
// and attribute mapping between systems.
class Identification extends SomNode {
  constructor(doc, path) {
    super(doc, path);
  }

  get content() {
    return new IdentificationContentForm(this.doc, this.path + "/content");
  }

  // Identity Sources — contains 0+× Identity Source.
  get identitySources() {
    return new SomList(this.doc, this.path + "/IDTSR-IDEN-LST", (d, p) => new IdentitySourceEntry(d, p));
  }

  // Identity Verification.
  get identityVerification() {
    return new IdentityVerificationPolicy(this.doc, this.path + "/identityVerification");
  }

  // Identity Providers — contains 0+× Identity Provider.
  get identityProviders() {
    return new SomList(this.doc, this.path + "/IDTPV-IDEN-LST", (d, p) => new IdentityProviderEntry(d, p));
  }

  // Single Sign-On.
  get singleSignOn() {
    return new SingleSignOnPolicy(this.doc, this.path + "/singleSignOn");
  }

  // Self-Registration.
  get selfRegistration() {
    return new SelfRegistrationPolicy(this.doc, this.path + "/selfRegistration");
  }

  // Attribute Mappings — contains 0+× Identity Attribute Mapping.
  get attributeMappings() {
    return new SomList(this.doc, this.path + "/IDTAM-ATTR-LST", (d, p) => new IdentityAttributeMappingEntry(d, p));
  }
}

